CREATE OR REPLACE FUNCTION public.audit_everything_with_subject()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    _user_id uuid;
    _resource public.audit_resource;
    _action public.audit_action;
    _resource_id text;
    _post_subject text;
    _rec RECORD; 
BEGIN
    IF (TG_OP = 'DELETE') THEN
        _action := 'DELETE';
        _rec := OLD;
    ELSIF (TG_OP = 'UPDATE') THEN
        _action := 'UPDATE';
        _rec := NEW;
    ELSE
        _action := 'CREATE';
        _rec := NEW;
    END IF;

    IF (TG_TABLE_NAME = 'posts') THEN
        _resource := 'POST';
        _resource_id := _rec.id;
        _post_subject := _rec.subject;
        SELECT uuid INTO _user_id FROM public.users 
        WHERE email = _rec.sender OR uuid::text = _rec.sender LIMIT 1;

    ELSIF (TG_TABLE_NAME = 'comments') THEN
        _resource := 'COMMENT';
        _resource_id := _rec.id::text;
        SELECT uuid INTO _user_id FROM public.users 
        WHERE email = _rec.sender OR uuid::text = _rec.sender LIMIT 1;
        SELECT subject INTO _post_subject 
        FROM public.posts WHERE id = _rec.post_id;

    ELSIF (TG_TABLE_NAME = 'likes') THEN
        _resource := 'LIKE';
        _user_id := _rec.user_id;
        _resource_id := _rec.id::text;

        IF (_rec.target_type = 'post') THEN
            SELECT subject INTO _post_subject 
            FROM public.posts WHERE id = _rec.target_id;
        ELSIF (_rec.target_type = 'comment') THEN
            SELECT p.subject INTO _post_subject
            FROM public.posts p
            JOIN public.comments c ON p.id = c.post_id
            WHERE c.id = _rec.target_id::bigint;
        -- article and other types: _post_subject stays NULL
        END IF;
    END IF;

    IF _user_id IS NULL THEN
        RETURN NULL;
    END IF;

    INSERT INTO public.user_audits (
        user_id, resource, request_type, resource_id, metadata
    ) VALUES (
        _user_id, _resource, _action, _resource_id,
        jsonb_build_object('post_subject', _post_subject)
    );

    RETURN NULL;
END;
$function$

