CREATE OR REPLACE FUNCTION public.people_search_users_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    DELETE FROM people_search_index WHERE user_uuid = OLD.uuid;
    RETURN OLD;
  END IF;
  BEGIN
    PERFORM people_search_refresh_user(NEW.uuid);
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'people_search_refresh_user(%) failed: %', NEW.uuid, SQLERRM;
  END;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.trg_user_activity_on_comment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_commenter_uuid  uuid;
  v_post_author     uuid;
BEGIN
  -- UUID מה-email של המגיב
  SELECT id INTO v_commenter_uuid
  FROM auth.users WHERE email = NEW.sender LIMIT 1;

  IF v_commenter_uuid IS NOT NULL THEN
    INSERT INTO user_activity (
      user_id, total_comments, last_comment_at, last_active_at, updated_at
    )
    VALUES (v_commenter_uuid, 1, now(), now(), now())
    ON CONFLICT (user_id) DO UPDATE SET
      total_comments  = user_activity.total_comments + 1,
      last_comment_at = now(),
      last_active_at  = now(),
      updated_at      = now();
  END IF;

  SELECT posted_by_uuid INTO v_post_author
  FROM posts WHERE id = NEW.post_id LIMIT 1;

  IF v_post_author IS NOT NULL AND v_post_author IS DISTINCT FROM v_commenter_uuid THEN
    INSERT INTO user_activity (user_id, total_comments_received, updated_at)
    VALUES (v_post_author, 1, now())
    ON CONFLICT (user_id) DO UPDATE SET
      total_comments_received = user_activity.total_comments_received + 1,
      updated_at = now();
  END IF;

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.trg_user_activity_on_like()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_post_author uuid;
BEGIN
  INSERT INTO user_activity (user_id, last_reaction_at, last_active_at, updated_at)
  VALUES (NEW.user_id, now(), now(), now())
  ON CONFLICT (user_id) DO UPDATE SET
    last_reaction_at = now(),
    last_active_at   = now(),
    updated_at       = now();

  BEGIN
    SELECT posted_by_uuid INTO v_post_author
    FROM posts WHERE id = NEW.target_id::uuid LIMIT 1;
  EXCEPTION WHEN invalid_text_representation THEN
    v_post_author := NULL;
  END;

  IF v_post_author IS NOT NULL AND v_post_author <> NEW.user_id THEN
    INSERT INTO user_activity (user_id, total_reactions_received, updated_at)
    VALUES (v_post_author, 1, now())
    ON CONFLICT (user_id) DO UPDATE SET
      total_reactions_received = user_activity.total_reactions_received + 1,
      updated_at = now();
  END IF;

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN RETURN NEW;
END;
$function$
